import React, { useState } from 'react';
import ReactFlow, { Controls, MiniMap } from 'reactflow';
import 'reactflow/dist/style.css';
import './index.css';
import { nodeTypes } from 'nodes';

function App() {
  const [nodes, setNodes] = useState([]);
  const [edges, setEdges] = useState([]);

  const handleSubmit = async () => {
    try {
      const response = await fetch('http://localhost:8000/pipelines/parse', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ nodes, edges }),
      });

      if (!response.ok) throw new Error('Network response was not ok');

      const result = await response.json();
      alert(
        `Pipeline Summary:\n` +
        `Nodes: ${result.num_nodes}\n` +
        `Edges: ${result.num_edges}\n` +
        `Is DAG: ${result.is_dag ? '✅ Yes' : '❌ No'}`
      );
    } catch (error) {
      alert('Failed to validate pipeline. Check console.');
    }
  };

  return (
    <div style={{ height: '100vh' }}>
      <button
        onClick={handleSubmit}
        className="absolute top-4 right-4 px-4 py-2 bg-purple-600 text-white rounded"
      >
        Submit Pipeline
      </button>

      <ReactFlow
        nodeTypes={nodeTypes}
        nodes={nodes}
        edges={edges}
        onNodesChange={(changes) => setNodes(prev => applyChanges(prev, changes))}
        onEdgesChange={(changes) => setEdges(prev => applyChanges(prev, changes))}
        fitView
      >
        <Controls />
        <MiniMap />
      </ReactFlow>
    </div>
  );
}

// Helper to apply changes to nodes/edges
const applyChanges = (items, changes) => {
  return changes.reduce((acc, change) => {
    if (change.type === 'remove') {
      return acc.filter(item => item.id !== change.id);
    }
    if (change.type === 'add') {
      return [...acc, change.item];
    }
    if (change.type === 'replace') {
      return acc.map(item => item.id === change.id ? change.item : item);
    }
    return acc;
  }, items);
};

export default App;
